import openpyxl
from datetime import datetime

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')
ws = wb.active

# Process rows 2 to 4 (data rows)
for row in range(2, 5):
    h_value = ws.cell(row=row, column=8).value  # Column H is column 8

    # Determine the result based on the conditions
    if h_value is None or h_value == '':
        # Cell H is blank
        result = 'No'
    elif isinstance(h_value, str):
        h_lower = h_value.strip().lower()
        if h_lower == 'yes':
            result = 'Yes'
        elif h_lower == 'n/a':
            result = 'N/A'
        else:
            # Check if it's a date string
            try:
                datetime.strptime(h_value.strip(), '%Y-%m-%d')
                result = 'Yes'
            except ValueError:
                try:
                    datetime.strptime(h_value.strip(), '%Y-%m-%d %H:%M:%S')
                    result = 'Yes'
                except ValueError:
                    result = 'No'
    elif isinstance(h_value, datetime):
        # It's a date object
        result = 'Yes'
    elif isinstance(h_value, (int, float)):
        # Check if it's a date serial number (Excel dates are numbers)
        # Excel dates are typically > 1 (since 1/1/1900 is 1)
        # But we need to be careful. Let's check if it's a reasonable date
        try:
            # Convert Excel serial date to Python date
            from openpyxl.utils.datetime import to_python_datetime
            dt = to_python_datetime(h_value)
            if dt:
                result = 'Yes'
            else:
                result = 'No'
        except:
            result = 'No'
    else:
        result = 'No'

    # Write the computed literal value to column J (column 10)
    ws.cell(row=row, column=10).value = result

# Save the workbook
wb.save('output.xlsx')
