import openpyxl

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')

# Get the sheets
sheet1 = wb['Sheet1']
summary = wb['Summary']

# Read data from Sheet1
# Columns: A=Status, B=Name, C=Type, D=Amt
# Data starts from row 2
data = []
for row in sheet1.iter_rows(min_row=2, values_only=True):
    status, name, type_val, amt = row
    if status is not None and name is not None and type_val is not None and amt is not None:
        data.append({
            'status': str(status).strip(),
            'name': str(name).strip().lower(),
            'type': str(type_val).strip(),
            'amt': float(amt)
        })

# Read names from Summary sheet (Column A, rows 2 to 6)
names = []
for row in summary.iter_rows(min_row=2, max_row=6, min_col=1, max_col=1, values_only=True):
    name = row[0]
    if name is not None:
        names.append(str(name).strip().lower())
    else:
        names.append(None)

# Define the status conditions
# HD and SD columns in Summary correspond to:
# Column B (HD): Sum where Type='HD' and Status is 'Completed' or 'Not Completed'
# Column C (SD): Sum where Type='SD' and Status is 'Completed' or 'Not Completed'
# Note: The problem states "HD & SD would be calculated from sheet 1 on basis of Status 'completed' or 'not completed'"
# This implies we exclude 'Scrapped' and any other status.

valid_statuses = {'completed', 'not completed'}

# Calculate sums for each name
results = {}
for name in names:
    if name is None:
        results[name] = {'HD': 0, 'SD': 0}
        continue

    hd_sum = 0
    sd_sum = 0

    for entry in data:
        if entry['name'] == name and entry['status'].lower() in valid_statuses:
            if entry['type'] == 'HD':
                hd_sum += entry['amt']
            elif entry['type'] == 'SD':
                sd_sum += entry['amt']

    results[name] = {'HD': hd_sum, 'SD': sd_sum}

# Write results to Summary sheet
# Column B is HD, Column C is SD
# Rows 2 to 6 correspond to the names
for i, name in enumerate(names):
    row_idx = i + 2  # Start from row 2
    if name is not None:
        hd_val = results[name]['HD']
        sd_val = results[name]['SD']
        summary.cell(row=row_idx, column=2, value=hd_val)
        summary.cell(row=row_idx, column=3, value=sd_val)
    else:
        summary.cell(row=row_idx, column=2, value=0)
        summary.cell(row=row_idx, column=3, value=0)

# Save the workbook
wb.save('output.xlsx')
