import openpyxl
from datetime import datetime

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')
ws = wb.active

# Define the days of the week mapping
days_of_week = {
    0: 'Mon',
    1: 'Tue',
    2: 'Wed',
    3: 'Thu',
    4: 'Fri',
    5: 'Sat',
    6: 'Sun'
}

# Extract holidays from columns H, I, J (Holiday Name, Date, Type)
# Holidays start from row 2
holidays = {}
for row in range(2, ws.max_row + 1):
    holiday_date_cell = ws.cell(row=row, column=9)  # Column I
    holiday_type_cell = ws.cell(row=row, column=10)  # Column J

    if holiday_date_cell.value is not None and holiday_type_cell.value is not None:
        # Parse the holiday date
        if isinstance(holiday_date_cell.value, datetime):
            holiday_date = holiday_date_cell.value.date()
        elif isinstance(holiday_date_cell.value, str):
            try:
                holiday_date = datetime.strptime(holiday_date_cell.value, '%Y-%m-%d %H:%M:%S').date()
            except ValueError:
                try:
                    holiday_date = datetime.strptime(holiday_date_cell.value, '%Y-%m-%d').date()
                except ValueError:
                    continue
        else:
            continue

        holiday_type = holiday_type_cell.value
        holidays[holiday_date] = holiday_type

# Process each date in column A and fill column E (WORKDAY)
for row in range(2, 76):  # Rows 2 to 75
    date_cell = ws.cell(row=row, column=1)  # Column A
    workday_cell = ws.cell(row=row, column=5)  # Column E

    if date_cell.value is not None:
        # Parse the date
        if isinstance(date_cell.value, datetime):
            date_obj = date_cell.value.date()
        elif isinstance(date_cell.value, str):
            try:
                date_obj = datetime.strptime(date_cell.value, '%Y-%m-%d %H:%M:%S').date()
            except ValueError:
                try:
                    date_obj = datetime.strptime(date_cell.value, '%Y-%m-%d').date()
                except ValueError:
                    workday_cell.value = ''
                    continue
        else:
            workday_cell.value = ''
            continue

        # Check if the date is a holiday
        if date_obj in holidays:
            workday_cell.value = holidays[date_obj]
        else:
            # Get the day of the week
            weekday = date_obj.weekday()
            workday_cell.value = days_of_week[weekday]
    else:
        workday_cell.value = ''

# Save the workbook
wb.save('output.xlsx')
